	protected DBTraceNamespaceSymbol assertIsNamespace(AbstractDBTraceSymbol symbol) {
		System.Diagnostics.Debug.Assert(symbol != null;
		if (!(symbol is DBTraceNamespaceSymbol)) {
			throw new AssertionError(
