	protected Iterable<TraceAddressSnapRange> getRanges() {
		return () => manager.idMap.getActiveSpaces()
				.stream()
				.flatMap(space => space.getUserIndex(typeof(long), DBTraceSymbolIDEntry.ID_COLUMN)
						.get(getID())
