	protected void set(string name, DBTraceNamespaceSymbol parent, SourceType source) {
		this.name = name;
		this.parentID = parent.getID();
		doSetSource(source);
		update(NAME_COLUMN, PARENT_COLUMN, FLAGS_COLUMN);

